import 'package:isar/isar.dart';

import '../../domain/entities/decision_enums.dart';

part 'isar_ai_insight.g.dart';

/// Mirrors AI_INSIGHTS. A read-only cache of server results: insights are
/// generated by the backend (Gemini), so the app never creates one locally
/// and this collection has no sync status.
@collection
class IsarAiInsight {
  Id localId = Isar.autoIncrement;

  @Index(unique: true)
  late String serverId; // Always present: only completed results are cached

  @Index(composite: [CompositeIndex('triggerContext')])
  late int decisionLocalId;
  late String decisionServerId;

  @Enumerated(EnumType.name)
  late TriggerContext triggerContext;

  late String modelVersion;
  late String insightText;

  @Enumerated(EnumType.name)
  BiasType? primaryBias;

  @Enumerated(EnumType.name)
  EmotionalTone? emotionalTone;

  @Enumerated(EnumType.name)
  RiskLevel? riskLevel;

  int? actionabilityScore; // 1–10
  String? suggestedAlternative;
  double? modelConfidence; // 0.0–1.0, drives the AI-limitations warning
  late DateTime generatedAt;
}
